class Solution {
public:
    int minimumTimeRequired(vector<int>& jobs, int k) {
        int n = jobs.size();
        int full = (1 << n) - 1;
        vector<int> sum(1 << n, 0);
        for (int mask = 1; mask <= full; mask++) {
            int low = mask & (-mask);
            int idx = __builtin_ctz(low);
            sum[mask] = sum[mask ^ low] + jobs[idx];
        }
        vector<int> dp(1 << n, INT_MAX);
        dp[0] = 0;
        for (int mask = 1; mask <= full; mask++) {
            dp[mask] = sum[mask];
        }
        for (int w = 1; w < k; w++) {
            vector<int> ndp(1 << n, INT_MAX);
            ndp[0] = 0;
            for (int mask = 1; mask <= full; mask++) {
                int best = INT_MAX;
                for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                    int prev = mask ^ sub;
                    int val = dp[prev];
                    if (sum[sub] > val) val = sum[sub];
                    if (val < best) best = val;
                }
                ndp[mask] = best;
            }
            dp = ndp;
        }
        return dp[full];
    }
};
